  ar: ['sa', 'eg', 'iq', 'sy', 'ma', 'dz', 'ye', 'sd', 'ae', 'jo', 'lb', 'ly', 'tn', 'om', 'kw', 'qa', 'bh', 'ps', 'mr', 'dj', 'km', 'so', 'td'],
